def Strongest_Extension(class_name, extensions):
    if not extensions:
        return class_name

    def strength(ext):
        cap = sum(1 for c in ext if c.isupper())
        sm = sum(1 for c in ext if c.islower())
        return cap - sm

    max_strength = None
    strongest_ext = None
    for ext in extensions:
        s = strength(ext)
        if max_strength is None or s > max_strength:
            max_strength = s
            strongest_ext = ext

